column2:
영화 테이블에서 상영 시간의 최댓값을 구해줘.,SELECT MAX(length) FROM film;,185,185,SELECT MAX(length) AS max_length FROM film;
등록된 영화 중 가장 긴 러닝타임은 몇 분이야?,SELECT MAX(length) FROM film;,185,185,SELECT MAX(length) AS max_length_minutes FROM film;
배우 ID가 1번인 배우가 출연한 영화의 총 편수는?,SELECT COUNT(*) FROM film_actor WHERE actor_id = 1;,19,19,SELECT COUNT(DISTINCT fa.film_id) AS film_count

언어 ID가 1번인 언어의 이름은?,SELECT name FROM language WHERE language_id = 1;,English,English             ,SELECT name FROM language WHERE language_id = 1;
1번 랭귀지 코드에 해당하는 언어 명칭을 출력해.,SELECT name FROM language WHERE language_id = 1;,English,Afghanistan,SELECT country FROM country WHERE country_id = 1;
결제 테이블에서 가장 큰 금액은 얼마인가?,SELECT MAX(amount) FROM payment;,11.99,11.99,SELECT MAX(amount) AS max_amount FROM payment;
지금까지 발생한 결제 내역 중 최고 액수를 알려줘.,SELECT MAX(amount) FROM payment;,11.99,11.99,SELECT MAX(amount) AS max_amount FROM payment;
직원 ID가 1번인 직원이 처리한 대여 건수는 총 몇 개인가?,SELECT COUNT(*) FROM rental WHERE staff_id = 1;,8040,8040,SELECT COUNT(*) AS rental_count
